"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Stars Over Port Andromeda', 'author': 'Signature original', 'genre': 'Deep Space Mysteries', 'chapters': [{'n': 1, 'title': 'Launch', 'text': "In the hold, under work lights, Captain Theo Brandt studied a quantum compass. It pulsed faintly, like a heart. 'home is the crew,' Captain Theo Brandt murmured. 'Let's find out what you are.'\n\nEngineer Pip Solano ran the numbers with grease on their hands and worry in their eyes. 'Pirate Queen Vex has three ships in the drift,' they said. 'If we burn hard, we can make it. If we burn hard, everyone will see us.'\n\nCaptain Theo Brandt gave the order anyway. The engines lit, the deck hummed, and the ship leapt toward a quantum compass with Port Andromeda falling behind. Some cargoes, Captain Theo Brandt knew, are worth the whole sky."}, {'n': 2, 'title': 'The Chart Unfolds', 'text': "They burned for the first waypoint with raiders on their tail. Captain Theo Brandt flew the ship like a thrown knife, skimming a gravity well so close the hull sang. Behind them, Pirate Queen Vex's vanguard broke off, unwilling to follow.\n\nEngineer Pip Solano cracked a quantum compass's casing with a spanner and a prayer. Inside: coordinates, a starlog, a voice saying one word over and over — the name of Port Andromeda.\n\nIn the quiet after, Captain Theo Brandt played the starlog again. The voice — old, tired, kind — said: 'Whoever finds this, Port Andromeda needs you. Hurry.' Captain Theo Brandt set the course and did not look back."}, {'n': 3, 'title': 'Storm Season', 'text': "The plasma storm hit at the second waypoint, a wall of fire across the sky. Engineer Pip Solano rerouted everything to the shields, hands flying, while Captain Theo Brandt threaded the ship through gaps that opened and closed like eyes.\n\nA mine took their port array. The deck went dark, then red. Engineer Pip Solano was already moving, cable in teeth, splicing by feel. 'Talk to me,' Captain Theo Brandt said, and Engineer Pip Solano talked — numbers, jokes, anything to keep the fear small.\n\nThe battle was short and ugly. Captain Theo Brandt used the storm itself as a weapon, luring the flagship into a plasma surge that stripped its shields. They escaped in the glare, hull scorched, crew cheering raggedly."}, {'n': 4, 'title': "The Traitor's Price", 'text': "Then a quantum compass spoke — fully, at last. Not a map but a key, and not to a place but to a shield: an ancient defense grid sleeping around Port Andromeda, the only thing that could stop Pirate Queen Vex's fleet.\n\nCaptain Theo Brandt let them live, confined to quarters. 'Pirate Queen Vex trades in hostages,' Captain Theo Brandt told the crew. 'We trade in something better.' It was a gamble; the crew's eyes said they knew it.\n\nCaptain Theo Brandt laughed for the first time in days. 'All this way,' they said, 'and we were carrying the lock, not the treasure.' Engineer Pip Solano was already calculating the wake-up sequence."}, {'n': 5, 'title': 'The Grid Awakens', 'text': "Silence, then. The grid humming. Port Andromeda safe below. Engineer Pip Solano put a hand on Captain Theo Brandt's shoulder and said what everyone was thinking: 'We live.'\n\nThe flagship came on anyway, and Captain Theo Brandt met it ship to ship above the burning sky. It was Pirate Queen Vex themselves on the viewscreen, offering one last deal. Captain Theo Brandt answered with the engines at full burn.\n\nThey reached Port Andromeda with Pirate Queen Vex's whole fleet behind them, a wall of iron against the stars. Captain Theo Brandt broadcast on all bands: 'People of Port Andromeda, wake the grid. Now.'"}, {'n': 6, 'title': 'Home Signal', 'text': "They landed at Port Andromeda to crowds and bells. The old voice from the starlog had belonged to the grid's last keeper, dead a hundred years; a quantum compass was their final message. Captain Theo Brandt laid it in the memorial with honors.\n\nEngineer Pip Solano was offered an admiralty and laughed in the committee's face. 'I have a ship,' they said. It was the highest compliment the crew had ever heard.\n\nAnd when the next distress call came — as it always does, out in the drift — the engines were already warm. There are always more skies. There is always Port Andromeda, somewhere, needing its heroes."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

